# name: shorter_longest_run_pref
# description: Among pairs with equal switch counts but different longest-run lengths, rate of choosing the sequence with the shorter longest run; observed above null_mean means the model under-penalises long streaks beyond what switch rate (and periodicity) explain.
def test_statistic(df):
    def lr(s):
        best = cur = 1
        for i in range(1, len(s)):
            cur = cur + 1 if s[i] == s[i - 1] else 1
            best = max(best, cur)
        return best
    a = df["sequence_a"]; b = df["sequence_b"]
    u = pd.unique(pd.concat([a, b]))
    d = {s: lr(s) for s in u}
    sw = {s: sum(1 for x, y in zip(s, s[1:]) if x != y) for s in u}
    ra = a.map(d).to_numpy(); rb = b.map(d).to_numpy()
    sa = a.map(sw).to_numpy(); sb = b.map(sw).to_numpy()
    m = (sa == sb) & (ra != rb)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy(dtype=float)[m]
    return float(np.mean(np.where((ra < rb)[m], y, 1 - y)))

# name: left_choice_rate
# description: Overall proportion of Left choices; observed above null_mean means a left-side response bias that the side-symmetric model does not produce.
def test_statistic(df):
    return float(df["chose_left"].astype(float).mean())

# name: perfect_alternation_choice
# description: Among pairs where exactly one sequence perfectly alternates (HTHT.../THTH...), rate of choosing it; observed below null_mean means the model over-predicts preference for perfect alternation (people find it too regular), above means it over-penalises it.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    u = pd.unique(pd.concat([a, b]))
    pa_ = {s: float(all(x != y for x, y in zip(s, s[1:]))) for s in u}
    xa = a.map(pa_).to_numpy(); xb = b.map(pa_).to_numpy()
    m = xa != xb
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy(dtype=float)[m]
    return float(np.mean(np.where((xa > xb)[m], y, 1 - y)))

# name: balance_pref_equal_switches
# description: Among pairs with equal switch counts but different H/T imbalance |#H-#T|, rate of choosing the more balanced sequence; observed above null_mean means people use H/T balance, which the alternation-only model under-uses.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    u = pd.unique(pd.concat([a, b]))
    sw = {s: sum(1 for x, y in zip(s, s[1:]) if x != y) for s in u}
    im = {s: abs(s.count("H") - s.count("T")) for s in u}
    ia = a.map(im).to_numpy(); ib = b.map(im).to_numpy()
    m = (a.map(sw).to_numpy() == b.map(sw).to_numpy()) & (ia != ib)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy(dtype=float)[m]
    return float(np.mean(np.where((ia < ib)[m], y, 1 - y)))

# name: symmetric_sequence_choice
# description: Among pairs where exactly one sequence is mirror-symmetric (a palindrome or the reverse of its H/T complement, e.g. HTTHHTTH, HHHHTTTT) and the other is not, rate of choosing the symmetric one; observed below null_mean means people penalise visible symmetry that the switch-rate+periodicity model does not capture.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    u = pd.unique(pd.concat([a, b]))
    tr = str.maketrans("HT", "TH")
    sym = {s: float(s == s[::-1] or s == s[::-1].translate(tr)) for s in u}
    xa = a.map(sym).to_numpy(); xb = b.map(sym).to_numpy()
    m = xa != xb
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy(dtype=float)[m]
    return float(np.mean(np.where((xa > xb)[m], y, 1 - y)))
